\u0064\u0049\u005b\u0050\u002c\u0061\u0037\u005d\u0048\u002c\u0057\u002a\u0041\u007a\u0073\u005b\u0046\u006f\u0056\u0039\u007d\u003f\u0037\u003a\u003d\u006d\u0074\u0071\u006c\u0036\u0062\u003f\u0048\u003f\u006d\u004a\u0079\u0022\u0063\u005b\u002f\u004a\u0054\u0043\u002b\u0058\u0029\u0028\u0067\u0028\u0046\u0069\u0074\u005a\u007e\u002f\u0040\u0030\u0029\u007b\u0028\u002e\u004d\u0036\u005d\u0069\u0067\u0058\u0067\u0033\u0048\u007e\u004a\u0036\u007b\u0050\u004c\u005b\u007b\u0060\u003f\u0028\u0034\u0035\u0048\u0055\u006a\u004e\u0044\u0075\u0049\u0050\u004a\u0046\u004b\u005d\u0045\u006a\u0034\u007a\u0029\u0053\u004a\u005d\u0034\u003c\u003c\u0034\u002c\u007e\u0073\u005a\u004c\u002b\u0048\u0066\u0022\u0033\u0075\u0033\u0055\u0023\u005d\u004a\u0072\u0049\u0032\u0037\u0032\u0068\u0035\u0061\u0022\u005a\u005f\u0052\u0057\u0025\u004b\u0036\u004b\u0053\u0047\u007b\u0067\u0035\u007d\u006b\u0041\u0028\u0050\u0047\u0068\u0034\u0063\u002c\u0042\u004b\u006d\u003d\u006b\u0041\u0023\u0035\u003d\u0042\u0049\u0075\u0044\u0025\u0021\u0077\u0076\u0033\u0051\u0055\u0025\u005d\u004d\u0056\u007d\u0061\u007e\u0040\u006b\u0075\u005e\u0032\u007a\u0044\u005f\u006e\u004e\u0034\u0051\u0053\u004b\u004f\u0040\u0076\u0022\u0047\u003c\u0047\u0064\u0021\u002f\u0039\u007a\u0061\u0061\u0072\u0070\u0042\u0067\u007a\u0076\u0022\u0055\u0055\u0065\u0028\u0064\u0074\u0030\u0054\u002a\u0046\u0048\u0060\u007d\u002c\u0030\u002a\u006f\u006c\u0064\u002f\u0057\u002a\u0074\u0073\u0072\u0055\u0041\u0070\u004d\u004c\u0048\u0024\u007d\u002e\u006e\u0078\u0055\u0026\u0022\u0074\u0024\u004b\u0038\u006c\u0079\u0021\u0039\u0074\u0033\u0061\u0068\u003d\u0028\u0047\u006a\u0044\u0069\u006e\u005b\u0039\u0072\u0053\u0072\u003e\u003c\u0060\u0042\u0057\u0041\u0039\u0040\u0033\u0057\u0062\u0061\u0044\u0058\u0037\u003f\u0051\u0047\u005e\u005e\u0052\u002e\u0025\u0063\u0064\u0023\u0023\u0059\u007e\u0062\u0056\u0064\u0069\u0051\u002a\u0040\u0034\u004a\u007e\u0057\u0037\u003f\u0061\u0079\u0045\u0047\u004e\u002b\u0024\u0025\u0062\u0035\u0035\u002a\u002f\u0046\u0063\u004c\u005f\u0029\u0025\u0069\u0057\u004f\u006e\u0047\u0068\u0033\u007a\u0052\u0069\u002c\u006b\u0064\u0050\u002e\u005a\u0079\u0038\u0061\u007c\u0049\u0067\u002e\u004c\u006d\u0048\u0076\u0025\u0062\u0061\u0054\u0067\u0063\u006c\u0047\u005e\u0045\u0058\u003d\u0037\u0068\u0060\u003a\u0045\u005d\u004d\u0042\u0055\u006e\u003d\u004e\u0070\u0022\u0076\u004c\u0065\u0045\u0031\u0059\u003c\u0053\u004e\u0073\u0074\u006d\u0036\u0079\u0023\u007c\u002f\u005b\u005f\u0076\u0022\u0069\u0063\u0050\u003a\u0026\u0075\u007b\u0032\u005a\u0037\u0069\u0044\u0031\u0073\u004c\u0073\u0056\u0070\u0056\u003e\u0078\u0031\u0053\u0071\u007c\u0058\u0074\u0051\u0026\u0072\u006d\u007b\u0021\u007e\u007a\u007b\u0021\u0044\u007e\u005e\u0046\u0029\u0025\u004c\u0043\u0071\u007e\u0051\u0038\u0026\u003c\u006e\u002f\u005f\u0025\u0023\u0056\u0060\u0069\u006a\u0067\u005b\u0034\u007e\u003f\u003b\u0065\u0041\u0072\u0023\u0045\u005d\u0038\u0030\u0052\u0025\u0064\u005a\u0062\u004b\u007d\u0051\u0064\u0025\u0039\u0074\u0069\u007a\u004f\u0071\u0062\u0052\u0039\u003e\u0039\u003e\u0072\u0025\u0069\u0066\u0065\u005f\u0042\u0071\u005a\u0055\u007a\u0046\u0022\u003e\u0023\u006d\u0072\u0041\u0066\u0025\u005f\u0055\u0023\u0063\u0057\u0065\u0073\u002c\u0032\u0039\u0048\u0023\u0037\u006f\u0043\u0050\u0060\u004f\u006e\u0069\u0041\u003e\u0044\u0035\u0021\u004d\u006a\u007c\u0051\u0063\u0063\u005f\u0061\u006f\u004c\u0035\u006e\u0064\u0030\u0041\u0039\u006f\u0041\u0052\u0024\u0044\u006c\u0025\u007c\u0021\u003a\u0028\u0048\u006c\u004e\u006d\u0032\u003d\u0030\u0035\u0041\u0059\u004a\u0025\u0067\u005e\u0029\u005b\u007e\u005d\u004a\u0051\u0045\u0061\u0031\u0035\u0037\u0045\u007d\u004b\u0079\u007c\u0025\u0062\u004c\u0072\u0079\u0044\u0049\u006f\u003d\u0025\u0039\u003c\u0050\u0043\u0061\u0071\u006d\u0029\u0036\u0048\u0031\u0028\u002c\u003f\u0053\u003b\u0022\u002b\u0058\u0022\u0058\u006a\u0073\u0077\u0025\u002f\u005e\u0048\u0066\u002e\u0036\u0062\u0073\u0066\u006d\u0037\u0039\u0079\u0063\u0031\u004e\u0040\u0028\u0035\u0042\u004f\u0063\u0067\u0036\u006d\u007d\u0054\u0028\u0029\u0072\u006f\u004a\u0040\u006f\u0034\u002b\u003f\u0031\u0028\u002c\u003f\u0053\u003b\u0031\u006f\u002b\u0036\u004c\u002b\u002f\u005e\u0048\u0066\u002e\u0036\u0062\u0073\u0066\u006d\u0037\u0039\u0079\u0063\u0031\u004e\u0040\u0028\u0036\u0039\u006c\u0070\u0045\u007d\u002f\u005e\u0048\u0066\u002e\u0036\u0062\u0073\u0066\u006d\u0037\u0039\u0079\u0063\u0031\u004e\u0040\u0028\u0036\u0039\u002c\u0053\u004f\u0049\u0066\u005d\u0072\u0056\u0022\u0043\u0079\u0063\u007b\u0031\u0059\u0023\u0072\u007c\u006f\u0028\u004e\u0062\u0072\u0061\u0067\u0047\u0078\u006d\u0051\u007d\u0033\u0077\u006f\u0078\u005a\u006d\u003d\u0077\u0077\u0039\u0026\u0070\u006c\u005b\u007e\u0049\u005f\u005a\u007c\u0053\u007a\u0048\u0071\u0034\u006f\u005f\u0024\u0036\u0079\u0074\u0060\u0029\u0049\u006f\u002c\u0070\u0036\u0028\u0023\u0038\u0076\u004b\u004a\u0053\u004c\u0064\u0075\u0059\u0074\u003f\u0045\u0063\u0062\u006e\u0072\u0060\u0048\u0070\u0041\u0041\u007a\u0044\u0068\u002b\u003e\u002c\u003a\u0070\u004f\u0076\u004a\u004f\u0021\u0051\u005d\u004d\u005d\u0043\u0075\u002f\u0040\u003b\u003d\u0073\u0055\u002a\u0041\u0058\u0035\u0067\u003f\u0077\u0055\u0024\u0070\u0074\u004b\u0036\u0061\u0038\u0069\u004b\u002c\u0023\u0024\u0076\u006a\u004e\u0062\u0075\u007a\u0035\u0070\u0063\u0049\u005d\u0037\u0068\u0069\u003e\u005e\u007d\u0038\u0067\u0078\u0071\u0074\u006e\u0070\u0063\u006e\u002b\u006c\u0068\u003d\u0063\u0049\u004e\u0044\u0070\u0026\u003b\u0061\u0072\u007d\u0056\u0038\u0069\u007e\u004c\u0070\u003d\u0026\u006f\u006b\u0049\u0048\u0053\u0071\u004c\u0068\u0070\u0063\u003f\u006c\u0038\u0030\u0069\u0043\u0068\u0043\u006a\u0025\u0052\u0061\u0058\u0053\u002e\u0074\u003c\u0028\u005e\u0055\u0068\u0062\u004e\u0061\u0077\u0026\u0076\u0045\u0033\u006d\u0044\u0060\u004a\u003e\u0063\u0023\u0067\u0043\u0038\u002a\u0048\u0067\u002f\u0041\u0031\u0065\u0021\u005f\u0063\u003e\u0037\u0037\u0067\u0043\u007e\u002b\u005b\u005d\u0043\u0071\u0038\u0040\u0042\u002f\u0050\u005d\u0043\u006e\u0050\u0029\u006c\u006a\u0078\u0031\u0075\u006f\u0043\u0078\u0063\u0078\u0076\u005d\u004e\u0060\u0073\u007c\u0045\u0036\u0065\u0068\u006b\u0045\u0058\u0041\u003a\u0034\u0038\u0037\u0030\u004d\u0055\u002c\u0035\u0061\u0069\u0026\u0066\u003f\u0025\u0035\u0070\u0063\u0049\u006c\u003c\u0030\u0061\u0049\u006b\u002b\u0029\u004d\u004f\u007a\u0035\u0051\u003b\u0060\u0063\u0077\u003d\u0050\u0079\u002c\u0022\u003a\u0053\u0067\u006b\u0045\u0058\u0041\u0043\u0041\u0072\u004b\u007b\u0056\u0025\u0034\u0022\u003a\u0068\u0067\u0036\u007a\u007d\u0057\u0029\u004f\u0035\u0032\u007b\u0056\u003e\u0035\u0062\u003a\u0049\u0065\u007b\u007a\u0035\u0051\u0065\u0036\u0021\u006c\u007b\u0044\u0047\u0070\u007e\u002b\u006a\u0023\u006c\u0029\u003c\u0040\u0069\u0043\u0061\u0029\u004d\u0062\u005d\u002f\u0078\u0029\u0056\u0045\u0040\u006d\u0047\u0041\u0045\u005f\u006d\u006f\u0023\u0069\u005f\u0059\u003a\u0035\u0021\u0028\u0029\u003b\u0024\u004d\u0079\u0040\u0022\u0051\u006a\u0032\u005b\u0048\u0036\u0025\u005b\u0032\u0056\u002e\u0026\u006f\u0065\u005a\u0066\u0037\u005f\u0036\u003e\u0037\u004b\u0033\u006c\u0042\u0026\u0043\u004a\u0032\u0024\u006a\u0060\u005e\u0054\u0048\u006d\u0039\u0044\u006c\u0042\u0077\u007b\u0029\u0048\u0066\u004c\u005f\u003e\u005b\u002a\u0063\u0067\u005f\u0029\u0079\u0036\u003e\u003e\u0024\u0051\u0059\u0058\u006b\u0055\u004b\u0063\u002b\u0044\u0057\u0069\u006b\u0042\u003a\u0025\u005e\u005e\u002f\u0076\u002e\u0036\u0055\u005d\u0023\u0078\u0060\u0052\u0038\u0023\u0065\u006d\u0031\u006a\u003b\u0072\u004f\u0024\u005f\u0037\u0031\u003b\u0038\u0050\u0029\u0023\u0036\u003f\u007d\u0075\u0073\u0036\u0030\u0059\u0069\u006d\u0046\u0041\u0071\u0074\u0059\u0053\u0068\u0046\u0053\u0077\u0030\u0030\u005f\u0051\u0039\u0030\u004a\u003b\u0053\u0057\u0040\u002c\u007e\u004b\u0054\u0077\u0056\u0034\u0021\u006b\u004a\u007d\u006f\u005d\u0021\u007b\u003a\u0058\u003f\u0059\u0071\u0065\u0056\u0069\u0045\u0051\u003b\u0075\u005e\u0075\u003a\u002f\u007e\u0023\u004a\u0077\u0043\u0023\u0076\u005d\u0075\u0062\u002f\u007c\u0039\u0069\u0078\u0039\u006d\u002a\u007b\u0049\u003d\u0055\u006b\u0040\u0029\u0062\u007c\u004a\u0026\u0042\u004f\u0051\u006e\u0029\u0070\u005a\u004f\u0060\u005a\u0033\u003e\u0046\u006b\u0030\u004d\u003f\u0035\u0050\u002e\u006f\u003f\u0043\u0055\u004c\u005b\u0038\u004a\u0072\u0025\u0026\u0050\u004c\u007a\u006c\u0026\u002f\u0065\u005d\u006a\u0070\u0049\u006c\u003a\u0072\u003a\u0048\u004b\u004e\u0059\u002e\u0063\u0033\u0061\u0042\u002e\u0048\u006e\u007c\u0034\u0025\u002f\u004a\u0056\u0065\u0033\u007c\u005d\u0070\u0036\u0021\u002e\u005b\u002c\u0058\u006c\u003e\u0034\u0025\u005d\u002f\u003b\u005e\u002f\u0038\u0039\u007a\u0070\u0067\u0066\u0031\u007a\u005a\u0054\u006c\u0037\u0060\u0069\u0030\u0053\u0059\u0067\u006c\u0058\u004e\u006b\u004b\u007a\u003b\u0047\u0051\u005d\u0061\u0037\u0060\u0026\u0034\u0073\u0056\u0069\u0059\u0058\u0077\u004e\u0026\u0069\u0073\u0029\u0062\u004d\u003d\u0072\u004b\u0053\u0063\u0051\u0069\u007e\u0077\u0043\u0057\u005a\u0026\u005f\u0076\u0068\u0065\u0063\u0063\u0054\u0064\u003e\u006b\u0025\u0034\u0040\u004a\u0037\u0056\u007a\u005a\u0079\u0057\u0046\u0050\u0063\u003f\u004e\u0057\u007e\u0058\u004e\u0028\u0051\u0028\u003b\u0070\u003d\u0044\u0045\u0063\u006a\u002f\u007e\u007b\u0076\u004d\u0069\u0040\u007d\u006a\u0033\u007c\u007d\u004c\u003b\u0070\u003d\u0044\u0045\u0063\u0031\u007e\u0038\u006f\u0064\u0078\u0035\u003a\u0066\u003f\u003e\u0037\u006c\u004e\u0028\u0067\u0031\u007e\u0038\u006f\u0064\u0078\u0035\u003a\u0066\u004f\u0044\u002b\u0048\u0052\u0047\u0041\u0074\u0048\u0048\u0064\u0021\u0073\u0023\u0042\u0049\u002a\u006a\u0062\u007e\u0034\u006e\u004b\u0021\u0067\u0063\u0047\u006f\u0068\u005e\u0034\u004f\u004d\u0074\u0058\u0061\u003a\u005b\u0052\u006c\u0021\u0021\u0035\u0075\u004c\u0062\u0059\u006c\u0021\u0030\u0053\u0075\u0042\u0065\u0070\u0046\u0021\u005b\u0052\u006c\u0021\u0021\u0035\u005e\u002a\u0073\u003f\u0054\u0071\u0063\u0041\u0048\u0074\u006a\u0046\u0060\u0061\u0077\u0076\u005f\u005e\u002a\u0073\u003f\u0054\u0071\u0063\u0041\u0048\u005a\u004d\u0046\u002b\u002b\u0062\u0074\u0048\u0034\u0064\u0021\u0073\u0023\u0042\u0049\u002a\u006a\u0062\u007e\u0065\u0042\u0040\u0069\u002b\u0062\u0074\u0048\u0034\u0064\u003f\u004e\u0028\u0021\u004c\u0029\u004d\u0074\u0048\u005b\u0078\u003f\u0055\u0044\u004b\u0036\u0068\u0026\u0041\u0068\u0044\u005d\u0061\u004f\u002a\u0033\u004b\u006a\u0066\u0054\u0041\u0024\u0054\u004b\u0029\u0042\u004c\u002c\u0057\u0069\u005d\u0060\u003e\u004f\u002a\u0033\u004b\u006a\u0066\u0054\u0041\u0024\u0077\u0025\u004b\u0021\u0074\u007c\u0060\u0021\u0055\u0036\u004c\u0053\u005a\u004a\u005e\u0039\u0023\u0078\u0061\u0032\u0038\u0071\u0021\u0074\u0022\u005e\u004a\u0060\u0059\u0028\u0063\u0021\u007a\u007c\u003a\u007b\u0065\u0036\u003a\u0043\u005f\u004e\u0045\u005f\u0035\u0053\u0056\u0049\u0070\u006e\u0041\u004f\u005a\u0077\u003c\u003b\u004c\u004e\u0030\u0031\u004f\u0062\u003d\u003c\u0079\u003f\u0073\u0047\u007e\u0044\u0056\u003a\u006b\u0076\u0029\u004c\u0060\u0039\u0063\u0038\u0054\u0065\u004e\u0070\u003d\u0033\u0033\u0049\u0078\u003e\u006d\u0055\u0062\u0031\u0026\u0050\u0056\u0034\u0044\u0045\u0068\u007c\u002f\u0037\u002f\u0028\u0076\u0042\u0036\u0025\u004c\u0062\u0036\u0047\u0051\u0030\u006c\u0051\u0036\u0077\u007c\u004f\u0049\u003c\u0071\u0073\u0057\u002c\u0023\u006d\u0026\u0066\u0061\u0052\u004a\u0074\u0054\u002f\u0021\u0023\u004f\u0058\u0050\u003d\u0039\u0046\u0075\u0037\u0052\u005d\u007d\u0067\u003a\u0033\u005e\u0075\u0022\u0021\u003e\u0039\u005e\u0057\u0068\u005d\u004f\u0049\u0022\u0035\u0048\u003c\u007b\u0022\u007c\u0070\u0071\u0078\u006a\u007c\u0025\u004c\u006b\u0026\u002a\u0040\u0071\u0021\u0056\u007d\u004c\u0048\u0079\u0059\u0052\u003e\u0038\u0066\u0071\u002b\u007b\u0047\u0039\u004a\u0074\u0078\u004e\u0044\u0055\u0063\u003f\u002c\u0028\u0073\u0046\u0070\u002c\u0042\u0033\u0050\u0032\u0068\u005a\u0063\u0055\u0022\u0022\u002c\u0028\u0023\u006d\u0034\u002f\u0028\u006e\u0073\u0036\u0067\u0042\u0072\u002f\u0028\u0054\u0072\u0030\u005e\u0026\u0024\u0050\u0076\u004f